S = "Hakeem Force Academy"
QS = [
(S, "Humayun was defeated by which ruler, forcing him to leave India in 1540?", ["Akbar", "Sher Shah Suri", "Ibrahim Lodhi", "Hemu"], 1, "Sher Shah Suri defeated Humayun at Chausa in 1539 and at Kannauj in 1540. Humayun then fled India.", "Humayun regained his throne in 1555 after defeating the Suri ruler Sikandar Suri.", [110]),
(S, "What is the capital of Hungary?", ["Vienna", "Prague", "Budapest", "Bucharest"], 2, "Budapest is the capital and largest city of Hungary. It lies on the River Danube.", "Budapest was formed in 1873 by joining Buda, Pest and Obuda.", [1082]),
(S, "What is the currency of Hungary?", ["Euro", "Forint", "Zloty", "Koruna"], 1, "Hungary uses its own currency, the forint (HUF). It has not adopted the euro.", "Poland uses the zloty and the Czech Republic uses the koruna.", [328]),
(S, "Who wrote the novel Ice Candy Man?", ["Bapsi Sidhwa", "Khushwant Singh", "Mohsin Hamid", "Kamila Shamsie"], 0, "Ice Candy Man (1988) was written by the Pakistani novelist Bapsi Sidhwa. It tells the story of Partition through a Parsi girl in Lahore.", "The novel was published in the USA as Cracking India and was filmed as 1947 Earth.", [24]),
(S, "Who won the ICC Men's Cricketer of the Year (Sir Garfield Sobers Trophy) award for 2022?", ["Ben Stokes", "Babar Azam", "Virat Kohli", "Shaheen Shah Afridi"], 1, "Babar Azam won the Sir Garfield Sobers Trophy for 2022 after scoring 2598 runs in all formats. He also won ICC ODI Cricketer of the Year.", "Shaheen Shah Afridi won the same trophy for 2021, and Ben Stokes was named Test Cricketer of the Year 2022.", [227, 4783]),
(S, "In which year was the Council of Islamic Ideology of Pakistan first established?", ["1956", "1962", "1973", "1979"], 1, "The Advisory Council of Islamic Ideology was set up under the 1962 Constitution. It was renamed Council of Islamic Ideology under the 1973 Constitution.", "The Council advises Parliament on whether laws are in line with Islam.", [593]),
(S, "In which year was the International Labour Organization (ILO) founded?", ["1919", "1929", "1945", "1948"], 0, "The ILO was created in 1919 under the Treaty of Versailles after World War I. It later became the first specialised agency of the United Nations in 1946.", "The ILO won the Nobel Peace Prize in 1969.", [2332]),
(S, "In which year did Pakistan become a member of the International Labour Organization (ILO)?", ["1947", "1950", "1956", "1962"], 0, "Pakistan has been an ILO member since 1947, the year of its independence.", "The ILO headquarters is in Geneva, Switzerland.", [3590, 2380]),
(S, "Who is the Managing Director of the International Monetary Fund (IMF) as of October 2026?", ["Christine Lagarde", "Kristalina Georgieva", "Dominique Strauss-Kahn", "David Malpass"], 1, "Kristalina Georgieva of Bulgaria has led the IMF since October 2019. Her 2026 listing as Managing Director was confirmed in IMF reports.", "Her predecessor was Christine Lagarde, and the head of the World Bank is a separate post.", [4564]),
(S, "Which commodity group is Pakistan's largest import by value?", ["Petroleum products and fuels", "Cotton", "Rice", "Tea"], 0, "Pakistan imports most of its oil needs, so mineral fuels and petroleum products are the largest import item by value.", "Pakistan's largest export by value is textiles.", [3129]),
(S, "Is the fraction 9/2 a proper or an improper fraction?", ["Proper fraction", "Improper fraction", "Mixed fraction", "Decimal fraction"], 1, "In 9/2 the numerator 9 is bigger than the denominator 2, so it is an improper fraction. It equals 4 and a half.", "A proper fraction has a numerator smaller than its denominator, like 2/9.", [307, 418]),
(S, "What is the date of Bangladesh's declaration of independence?", ["16 December 1971", "26 March 1971", "14 August 1971", "23 March 1971"], 1, "Bangladesh declared independence on 26 March 1971 and celebrates it as Independence Day. The war ended on 16 December 1971.", "16 December is celebrated in Bangladesh as Victory Day.", [428, 1093, 3574]),
(S, "On which date did Israel declare its independence?", ["14 May 1948", "15 August 1947", "1 January 1948", "5 June 1967"], 0, "David Ben-Gurion declared the State of Israel on 14 May 1948, as the British Mandate ended.", "Israel celebrates its Independence Day by the Hebrew calendar, so the Gregorian date changes each year.", [987]),
(S, "Which Indian leader signed the Tashkent Declaration of 1966 with Pakistan's Ayub Khan?", ["Jawaharlal Nehru", "Lal Bahadur Shastri", "Indira Gandhi", "Morarji Desai"], 1, "Indian Prime Minister Lal Bahadur Shastri signed the Tashkent Declaration on 10 January 1966. The Soviet Union mediated.", "Shastri died in Tashkent a few hours after signing the agreement.", [4031]),
(S, "What is the antonym of the word indifference?", ["Apathy", "Concern", "Neglect", "Calmness"], 1, "Indifference means lack of interest. Its opposite is concern, meaning care or interest.", "Apathy and unconcern are synonyms of indifference.", [2984]),
(S, "Who held the Foreign Affairs (External Affairs) portfolio in the Interim Government of 1946?", ["Liaquat Ali Khan", "Jawaharlal Nehru", "Sardar Patel", "Rajendra Prasad"], 1, "Jawaharlal Nehru was Vice President of the Interim Government and held External Affairs and Commonwealth Relations.", "Liaquat Ali Khan held the Finance portfolio in the same government.", [4703]),
(S, "Which country did Germany invade first at the start of World War II in 1939?", ["France", "Poland", "Czechoslovakia", "Belgium"], 1, "Germany invaded Poland on 1 September 1939. Britain and France then declared war on Germany.", "Germany had earlier taken over Czechoslovakia in 1938 and 1939 without a war.", [2361, 3929, 4349]),
(S, "Who invented the television?", ["Thomas Edison", "John Logie Baird", "Alexander Graham Bell", "Guglielmo Marconi"], 1, "Scottish engineer John Logie Baird demonstrated the first working television in 1926.", "Sources differ, and some credit Philo Farnsworth for the first fully electronic television.", [4458]),
]
